mapper.select:
select  from qms_defect d
d.use_yn = #{useYn}
order by (select k.sort_no from sys_code k where k.grp_cd = 'DEFECT_CAT' and k.code = d.cat_cd), d.sort_no, d.defect_cd

mapper.sql:
from qms_defect d

    and d.use_yn = #{useYn}
    and (d.defect_cd ilike #{kw} escape '\' or d.defect_nm ilike #{kw} escape '\')

mapper.update:
update qms_defect
   set defect_nm = #{f.defectNm}, cat_cd = #{f.catCd}, sort_no = #{f.sortNo}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where defect_id = #{id} and row_ver = #{f.rowVer}

update mst_term_alias
   set alias = #{f.alias}, lang = #{f.lang}, use_yn = #{f.useYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where alias_id = #{id} and row_ver = #{f.rowVer}
